//! Translate the supported Chat Completions subset to ChatGPT plan Responses.
use serde_json::{json,Value};

pub(crate) fn request(value:&Value)->Result<(Value,bool),String>{
 let source=value.as_object().ok_or("Requête Chat invalide.")?;
 for(key,value)in source{if !matches!(key.as_str(),"model"|"messages"|"stream"|"tools"|"tool_choice"|"parallel_tool_calls"|"max_tokens"|"max_completion_tokens")&&!value.is_null(){return Err(format!("Option Chat non prise en charge pour ChatGPT : {key}."))}}
 let model=value.get("model").and_then(Value::as_str).filter(|s|!s.is_empty()).ok_or("Modèle manquant.")?;
 let stream=match value.get("stream"){None=>false,Some(v)=>v.as_bool().ok_or("Option de flux invalide.")?};
 let messages=value.get("messages").and_then(Value::as_array).filter(|v|v.len()<=512).ok_or("Messages invalides.")?;let mut input=Vec::new();let mut instructions=Vec::new();
 for msg in messages{let role=msg.get("role").and_then(Value::as_str).ok_or("Rôle manquant.")?;let object=msg.as_object().ok_or("Message invalide.")?;for(key,value)in object{let allowed=match role{"assistant"=>matches!(key.as_str(),"role"|"content"|"tool_calls"),"tool"=>matches!(key.as_str(),"role"|"content"|"tool_call_id"),_=>matches!(key.as_str(),"role"|"content")};if !allowed&&!value.is_null(){return Err(format!("Champ de message non pris en charge : {key}."))}}
  match role{
   "system"|"developer"=>{if !input.is_empty(){return Err("Instructions après le début de la conversation non prises en charge.".into())}let text=msg.get("content").and_then(Value::as_str).ok_or("Instructions non textuelles non prises en charge.")?;instructions.push(text.to_owned());},
   "user"|"assistant"=>{
    if let Some(text)=msg.get("content").and_then(Value::as_str){input.push(json!({"type":"message","role":role,"content":text}));}
    else if let Some(parts)=msg.get("content").and_then(Value::as_array){let mut converted=Vec::new();if parts.len()>256{return Err("Trop de blocs dans le message.".into())}for part in parts{match part.get("type").and_then(Value::as_str){
     Some("text")=>{let text=part.get("text").and_then(Value::as_str).ok_or("Texte invalide.")?;converted.push(json!({"type":if role=="assistant"{"output_text"}else{"input_text"},"text":text}));},
     Some("image_url") if role=="user"=>{let image=part.get("image_url").and_then(Value::as_object).ok_or("Image invalide.")?;if image.keys().any(|key|!matches!(key.as_str(),"url"|"detail")){return Err("Option d’image non prise en charge.".into())}let url=image.get("url").and_then(Value::as_str).filter(|url|!url.is_empty()&&url.len()<=12*1024*1024&&!url.chars().any(char::is_control)).ok_or("Image invalide.")?;let valid_data=["data:image/png;base64,","data:image/jpeg;base64,","data:image/webp;base64,","data:image/gif;base64,"].iter().any(|prefix|url.strip_prefix(prefix).is_some_and(|v|!v.is_empty()));let valid_url=reqwest::Url::parse(url).ok().is_some_and(|url|matches!(url.scheme(),"http"|"https")&&url.host_str().is_some()&&url.username().is_empty()&&url.password().is_none());if !valid_data&&!valid_url{return Err("Adresse d’image non prise en charge.".into())}let mut image_part=json!({"type":"input_image","image_url":url});if let Some(detail)=image.get("detail"){let detail=detail.as_str().filter(|v|matches!(*v,"auto"|"low"|"high"|"original")).ok_or("Détail d’image invalide.")?;image_part["detail"]=json!(detail)}converted.push(image_part);},
     _=>return Err("Contenu non pris en charge.".into())
    }}input.push(json!({"type":"message","role":role,"content":converted}));}
    else if !msg.get("content").is_none_or(Value::is_null){return Err("Contenu non textuel non pris en charge.".into())}
    if let Some(calls)=msg.get("tool_calls").filter(|v|!v.is_null()){
     if role!="assistant"{return Err("Appel d’outil invalide.".into())}for call in calls.as_array().filter(|v|v.len()<=128).ok_or("Appels d’outils invalides.")?{
      if call.get("type").and_then(Value::as_str)!=Some("function"){return Err("Type d’outil non pris en charge.".into())}
      let id=call.get("id").and_then(Value::as_str).filter(|s|!s.is_empty()).ok_or("Identifiant d’outil manquant.")?;let name=call.pointer("/function/name").and_then(Value::as_str).filter(|s|!s.is_empty()).ok_or("Nom d’outil manquant.")?;let args=call.pointer("/function/arguments").and_then(Value::as_str).ok_or("Arguments d’outil invalides.")?;input.push(json!({"type":"function_call","call_id":id,"name":name,"arguments":args}));
     }
    }
   },
   "tool"=>{let id=msg.get("tool_call_id").and_then(Value::as_str).filter(|v|!v.is_empty()).ok_or("Identifiant d’outil manquant.")?;let content=msg.get("content").and_then(Value::as_str).ok_or("Résultat d’outil non textuel.")?;input.push(json!({"type":"function_call_output","call_id":id,"output":content}));},
   _=>return Err("Rôle Chat non pris en charge.".into())
  }
 }
 let mut response=json!({"model":model,"input":input,"stream":true,"store":false});if !instructions.is_empty(){response["instructions"]=json!(instructions.join("\n\n"));}
 if let Some(tools)=value.get("tools").filter(|v|!v.is_null()){let mut converted=Vec::new();for tool in tools.as_array().filter(|v|v.len()<=128).ok_or("Outils invalides.")?{if tool.get("type").and_then(Value::as_str)!=Some("function"){return Err("Type d’outil non pris en charge.".into())}let function=tool.get("function").and_then(Value::as_object).ok_or("Outil invalide.")?;let mut item=function.clone();item.insert("type".into(),json!("function"));converted.push(Value::Object(item));}response["tools"]=json!(converted);}
 if let Some(choice)=value.get("tool_choice").filter(|v|!v.is_null()){response["tool_choice"]=if choice.get("type").and_then(Value::as_str)==Some("function"){let name=choice.pointer("/function/name").and_then(Value::as_str).filter(|name|!name.is_empty()).ok_or("Sélection d’outil invalide.")?;json!({"type":"function","name":name})}else if choice.as_str().is_some_and(|s|matches!(s,"auto"|"none"|"required")){choice.clone()}else{return Err("Sélection d’outil non prise en charge.".into())};}
 if let Some(v)=value.get("parallel_tool_calls"){if !v.is_boolean(){return Err("Option d’outils invalide.".into())}response["parallel_tool_calls"]=v.clone();}
 if value.get("max_tokens").is_some()&&value.get("max_completion_tokens").is_some(){return Err("Limites de sortie incompatibles.".into())}
 if let Some(limit)=value.get("max_completion_tokens").or_else(||value.get("max_tokens")){if !limit.as_u64().is_some_and(|v|v>0){return Err("Limite de sortie invalide.".into())}response["max_output_tokens"]=limit.clone();}
 Ok((response,stream))
}

pub(crate) fn messages_stream(value:&Value)->Result<String,String>{
 let content=value.get("content").and_then(Value::as_array).ok_or("Réponse Messages invalide.")?;let id=value.get("id").and_then(Value::as_str).ok_or("Identifiant Messages absent.")?;let model=value.get("model").and_then(Value::as_str).ok_or("Modèle Messages absent.")?;let usage=value.get("usage").ok_or("Usage Messages absent.")?;let input=usage.get("input_tokens").and_then(Value::as_u64).ok_or("Usage Messages invalide.")?;let output=usage.get("output_tokens").and_then(Value::as_u64).ok_or("Usage Messages invalide.")?;
 let event=|kind:&str,mut data:Value|{data["type"]=json!(kind);format!("event: {kind}\ndata: {data}\n\n")};let mut result=event("message_start",json!({"message":{"id":id,"type":"message","role":"assistant","content":[],"model":model,"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":input,"output_tokens":0}}}));
 for(index,part)in content.iter().enumerate(){match part.get("type").and_then(Value::as_str){Some("text")=>{let text=part.get("text").and_then(Value::as_str).ok_or("Texte invalide.")?;result.push_str(&event("content_block_start",json!({"index":index,"content_block":{"type":"text","text":""}})));result.push_str(&event("content_block_delta",json!({"index":index,"delta":{"type":"text_delta","text":text}})));},Some("tool_use")=>{let id=part.get("id").and_then(Value::as_str).ok_or("Outil invalide.")?;let name=part.get("name").and_then(Value::as_str).ok_or("Outil invalide.")?;let args=part.get("input").filter(|v|v.is_object()).ok_or("Outil invalide.")?.to_string();result.push_str(&event("content_block_start",json!({"index":index,"content_block":{"type":"tool_use","id":id,"name":name,"input":{}}})));result.push_str(&event("content_block_delta",json!({"index":index,"delta":{"type":"input_json_delta","partial_json":args}})));},_=>return Err("Bloc Messages non pris en charge.".into())}result.push_str(&event("content_block_stop",json!({"index":index})));}
 result.push_str(&event("message_delta",json!({"delta":{"stop_reason":value["stop_reason"],"stop_sequence":null},"usage":{"output_tokens":output}})));result.push_str(&event("message_stop",json!({})));Ok(result)
}

pub(crate) fn completed(events:&str,model:&str,allowed:&std::collections::BTreeSet<String>)->Result<Value,String>{
 let normalized=events.replace("\r\n","\n");let mut last=None;for event in normalized.split("\n\n"){
  let data=event.lines().filter_map(|line|line.strip_prefix("data:").map(str::trim_start)).collect::<Vec<_>>().join("\n");if data.is_empty()||data=="[DONE]"{continue}
  let value:Value=serde_json::from_str(&data).map_err(|_|"Flux ChatGPT illisible.")?;
  match value.get("type").and_then(Value::as_str){Some("response.failed"|"error")=>return Err("ChatGPT n’a pas terminé la réponse.".into()),Some("response.completed"|"response.incomplete")=>{if last.is_some(){return Err("Flux ChatGPT incohérent.".into())}last=value.get("response").cloned();},_=>{}}
 }
 let response=last.ok_or("Flux ChatGPT interrompu avant la fin.")?;let output=response.get("output").and_then(Value::as_array).ok_or("Réponse ChatGPT incomplète.")?;
 let mut text=String::new();let mut calls=Vec::new();for item in output{match item.get("type").and_then(Value::as_str){
  Some("message")=>for part in item.get("content").and_then(Value::as_array).ok_or("Message ChatGPT invalide.")?{match part.get("type").and_then(Value::as_str){Some("output_text")=>text.push_str(part.get("text").and_then(Value::as_str).ok_or("Texte ChatGPT invalide.")?),Some("refusal")=>return Err("La réponse a été refusée par ChatGPT.".into()),_=>return Err("Contenu ChatGPT non pris en charge.".into())}},
  Some("function_call")=>{let id=item.get("call_id").and_then(Value::as_str).ok_or("Appel d’outil sans identifiant.")?;let name=item.get("name").and_then(Value::as_str).filter(|name|allowed.contains(*name)).ok_or("Outil ChatGPT non déclaré.")?;let arguments=item.get("arguments").and_then(Value::as_str).ok_or("Arguments d’outil invalides.")?;calls.push(json!({"id":id,"type":"function","function":{"name":name,"arguments":arguments}}));},
  Some("reasoning")=>{},_=>return Err("Sortie ChatGPT non prise en charge.".into())
 }}
 let finish=if !calls.is_empty(){"tool_calls"}else if response.get("status").and_then(Value::as_str)==Some("incomplete"){match response.pointer("/incomplete_details/reason").and_then(Value::as_str){Some("max_output_tokens")=>"length",Some("content_filter")=>"content_filter",_=>return Err("Réponse ChatGPT incomplète sans raison reconnue.".into())}}else if response.get("status").and_then(Value::as_str)==Some("completed"){"stop"}else{return Err("État final ChatGPT invalide.".into())};let mut message=json!({"role":"assistant","content":if text.is_empty(){Value::Null}else{json!(text)}});if !calls.is_empty(){message["tool_calls"]=json!(calls)}
 let mut result=json!({"id":format!("chatcmpl-{}",uuid::Uuid::new_v4().simple()),"object":"chat.completion","created":std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs(),"model":model,"choices":[{"index":0,"message":message,"finish_reason":finish}]});
 if let Some(usage)=response.get("usage").filter(|v|v.is_object()){let input=usage.get("input_tokens").and_then(Value::as_u64).ok_or("Usage ChatGPT invalide.")?;let output=usage.get("output_tokens").and_then(Value::as_u64).ok_or("Usage ChatGPT invalide.")?;result["usage"]=json!({"prompt_tokens":input,"completion_tokens":output,"total_tokens":usage.get("total_tokens").and_then(Value::as_u64).unwrap_or(input+output)});}
 Ok(result)
}

pub(crate) struct TextStream{pending:Vec<u8>,data:Vec<String>,emitted:String,id:String,model:String,created:u64,done:bool}
impl TextStream{
 pub(crate) fn new(model:String)->Self{Self{pending:Vec::new(),data:Vec::new(),emitted:String::new(),id:format!("chatcmpl-{}",uuid::Uuid::new_v4().simple()),model,created:std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs(),done:false}}
 fn frame(&self,delta:Value,finish:Option<&str>)->bytes::Bytes{let event=json!({"id":self.id,"object":"chat.completion.chunk","created":self.created,"model":self.model,"choices":[{"index":0,"delta":delta,"finish_reason":finish}]});bytes::Bytes::from(format!("data: {event}\n\n"))}
 pub(crate) fn start(&self)->bytes::Bytes{self.frame(json!({"role":"assistant"}),None)}
 pub(crate) fn done(&self)->bool{self.done}
 pub(crate) fn ingest(&mut self,chunk:&[u8])->Result<Vec<bytes::Bytes>,String>{
  if self.done{return Ok(Vec::new())}if self.pending.len()+chunk.len()>16*1024*1024{return Err("Flux ChatGPT trop volumineux.".into())}self.pending.extend_from_slice(chunk);let mut output=Vec::new();
  while let Some(pos)=self.pending.iter().position(|byte|*byte==b'\n'){
   let line:Vec<u8>=self.pending.drain(..=pos).collect();let line=std::str::from_utf8(&line[..line.len()-1]).map_err(|_|"Flux ChatGPT illisible.")?.trim_end_matches('\r');
   if line.is_empty(){if self.data.is_empty(){continue}let data=std::mem::take(&mut self.data).join("\n");if data=="[DONE]"{continue}let value:Value=serde_json::from_str(&data).map_err(|_|"Événement ChatGPT illisible.")?;
    match value.get("type").and_then(Value::as_str){
     Some("response.output_text.delta")=>{let delta=value.get("delta").and_then(Value::as_str).ok_or("Fragment ChatGPT invalide.")?;if self.emitted.len()+delta.len()>8*1024*1024{return Err("Réponse ChatGPT trop volumineuse.".into())}self.emitted.push_str(delta);if !delta.is_empty(){output.push(self.frame(json!({"content":delta}),None))}},
     Some("response.completed"|"response.incomplete")=>{let result=completed(&format!("data: {data}\n\n"),&self.model,&std::collections::BTreeSet::new())?;let full=result["choices"][0]["message"]["content"].as_str().unwrap_or("");if !full.starts_with(&self.emitted){return Err("Le texte final ChatGPT ne correspond pas au flux.".into())}let remainder=&full[self.emitted.len()..];if !remainder.is_empty(){output.push(self.frame(json!({"content":remainder}),None))}let reason=result["choices"][0]["finish_reason"].as_str().ok_or("État final ChatGPT invalide.")?;output.push(self.frame(json!({}),Some(reason)));output.push(bytes::Bytes::from_static(b"data: [DONE]\n\n"));self.done=true;break},
     Some("response.failed"|"error"|"response.refusal.delta")=>return Err("La réponse ChatGPT a échoué ou a été refusée.".into()),
     Some("response.output_item.added") if value.pointer("/item/type").and_then(Value::as_str)==Some("function_call")=>return Err("Appel d’outil ChatGPT non déclaré.".into()),
     _=>{}
    }
   }else if let Some(data)=line.strip_prefix("data:"){let data=data.strip_prefix(' ').unwrap_or(data);if self.data.len()>=8192||self.data.iter().map(String::len).sum::<usize>()+data.len()>16*1024*1024{return Err("Événement ChatGPT trop volumineux.".into())}self.data.push(data.to_owned());}
  }Ok(output)
 }
}

#[cfg(test)]mod tests{use super::*;
 #[test]fn request_preserves_text_and_tool_roundtrip(){let (result,stream)=request(&json!({"model":"gpt-test","stream":false,"messages":[{"role":"system","content":"help"},{"role":"user","content":"hello"},{"role":"assistant","content":null,"tool_calls":[{"id":"call1","type":"function","function":{"name":"read","arguments":"{}"}}]},{"role":"tool","tool_call_id":"call1","content":"result"}],"tools":[{"type":"function","function":{"name":"read","parameters":{"type":"object"}}}]})).unwrap();assert!(!stream);assert_eq!(result["instructions"],"help");assert_eq!(result["input"][1]["call_id"],"call1");assert_eq!(result["input"][2]["output"],"result");assert_eq!(result["tools"][0]["name"],"read");assert_eq!(result["stream"],true);assert_eq!(result["store"],false);}
 #[test]fn rejects_unknown_options_and_non_text(){assert!(request(&json!({"model":"m","messages":[],"temperature":0.5})).is_err());assert!(request(&json!({"model":"m","messages":[{"role":"user","content":[{"type":"image_url"}]}]})).is_err());}
 #[test]fn completed_turn_maps_text_tools_and_usage(){let events="data: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\",\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"Bonjour\"}]},{\"type\":\"function_call\",\"call_id\":\"c1\",\"name\":\"read\",\"arguments\":\"{}\"}],\"usage\":{\"input_tokens\":3,\"output_tokens\":2}}}\n\n";let allowed=std::collections::BTreeSet::from(["read".to_owned()]);let value=completed(events,"provider/m",&allowed).unwrap();assert_eq!(value["choices"][0]["message"]["content"],"Bonjour");assert_eq!(value["choices"][0]["message"]["tool_calls"][0]["id"],"c1");assert_eq!(value["choices"][0]["finish_reason"],"tool_calls");assert_eq!(value["usage"]["total_tokens"],5);assert!(completed(events,"m",&std::collections::BTreeSet::new()).is_err());assert!(completed("data: {\"type\":\"response.created\"}\n\n","m",&allowed).is_err());}
 #[test]fn messages_stream_includes_text_tools_usage_and_stop(){let message=json!({"id":"msg_test","model":"m","content":[{"type":"text","text":"hello"},{"type":"tool_use","id":"call1","name":"read","input":{"path":"file"}}],"stop_reason":"tool_use","usage":{"input_tokens":5,"output_tokens":3}});let stream=messages_stream(&message).unwrap();assert!(stream.contains("event: message_start"));assert!(stream.contains("event: content_block_delta"));assert!(stream.contains("input_json_delta"));assert!(stream.contains("\\\"path\\\":\\\"file\\\""));assert!(stream.contains("\"output_tokens\":3"));assert!(stream.ends_with("event: message_stop\ndata: {\"type\":\"message_stop\"}\n\n"));}
 #[test]fn messages_text_blocks_convert_to_chatgpt_input(){let input=json!({"model":"m","max_tokens":100,"messages":[{"role":"user","content":[{"type":"text","text":"un"},{"type":"text","text":"deux"}]}]});let(chat,_)=crate::messages_adapter::request(&input).unwrap();let(responses,_)=request(&chat).unwrap();assert_eq!(responses["input"][0]["content"][0]["text"],"un");assert_eq!(responses["input"][0]["content"][1]["text"],"deux");assert_eq!(responses["max_output_tokens"],100);}
 #[test]fn converts_chat_and_messages_images_in_order(){let chat=json!({"model":"m","messages":[{"role":"user","content":[{"type":"text","text":"regarde"},{"type":"image_url","image_url":{"url":"https://example.org/a.png","detail":"high"}},{"type":"text","text":"fin"}]}]});let(result,_)=request(&chat).unwrap();assert_eq!(result["input"][0]["content"][0]["type"],"input_text");assert_eq!(result["input"][0]["content"][1]["type"],"input_image");assert_eq!(result["input"][0]["content"][1]["detail"],"high");assert_eq!(result["input"][0]["content"][2]["text"],"fin");let messages=json!({"model":"m","max_tokens":20,"messages":[{"role":"user","content":[{"type":"image","source":{"type":"base64","media_type":"image/png","data":"AA=="}}]}]});let(chat,_)=crate::messages_adapter::request(&messages).unwrap();let(result,_)=request(&chat).unwrap();assert_eq!(result["input"][0]["content"][0]["image_url"],"data:image/png;base64,AA==");}
 #[test]fn text_stream_emits_fragments_before_completion_and_validates_end(){let mut stream=TextStream::new("m".into());let first=stream.ingest(b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"Bon\"}\n\n").unwrap();assert_eq!(first.len(),1);assert!(std::str::from_utf8(&first[0]).unwrap().contains("Bon"));assert!(!stream.done());let final_event=b"data: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\",\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"Bonjour\"}]}]}}\n\n";let rest=stream.ingest(final_event).unwrap();assert!(stream.done());assert_eq!(rest.len(),3);assert!(std::str::from_utf8(&rest[0]).unwrap().contains("jour"));let mut bad=TextStream::new("m".into());bad.ingest(b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"wrong\"}\n\n").unwrap();assert!(bad.ingest(final_event).is_err());}
}
